{
 "research_concepts": [
  "Player roles (shapers)",
  "Offensive play types (cuts, drives)",
  "Player transferability/portability",
  "Player impact after team change"
 ],
 "methodological_questions": [
  "Player classification (cut-heavy vs. drive-heavy)",
  "Defining 'shaper' roles",
  "Measuring role portability/impact change after transfer",
  "Controlling for confounding factors in player movement studies",
  "Reliability of play-type labels"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-057",
   "status_as_recorded": "supported",
   "finding": "Pre-move cut share (vs drive share) predicts whether a connector's organizational function reproduces after a move. Cut share rho=+0.265 p=0.011 AUC 0.653. Cut-drive rho=+0.314 p=0.002 AUC 0.656. Drive rho=-0.278 p=0.007. Top cut tercile 65% portable median Delta +0.167; bottom 35% median -0.039."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail. 'play type labels have systematic issues that undermine adaptation findings'; foul possessions leak into OTHER."
  },
  {
   "id": "FAM:SF-CHT-087",
   "status_as_recorded": "artifact",
   "finding": "Portability median Delta is robust to pairing rule among 428 movers with n_decoys>=3. Organizer-connector gap CI includes 0 after correcting a menu-similarity confound; KW p=0.047 is population-level, pairwise is suggestive."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality). FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0. Flat non-decaying lifts collapse under within-team baseline; team-quality confound."
  },
  {
   "id": "FAM:SF-APPS-073",
   "status_as_recorded": "artifact",
   "finding": "Running play type X raises the same team's next 1-5 possession PPP vs a matched baseline (action memory). Global horizons: DRIVE/SPOT_UP/TRANSITION=5; others 0 (PNR/CUT/POST_UP/PUTBACK). SPOT_UP lag-1 lift +0.027 ctrl_p=0.0000. Within-team: all horizons 0 except SPOT_UP horizon(all)=1; PNR lag-1 within_team_lift=-0.0218. Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1."
  },
  {
   "id": "FAM:SF-APPS-011",
   "status_as_recorded": "supported",
   "finding": "DRIVE PPP is materially higher in RS than playoffs, so an RS-calibrated optimizer over-recommends DRIVE. DRIVE RS 1.198 vs PO 0.912 (-0.286, 25 teams); PNR -0.173; PULL_UP +0.301; others within -0.07."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Play-type label accuracy audit",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw), LIM:label_or_classification_error, LIM:leakage, LIM:small_sample. 'play type labels have systematic issues that undermine adaptation findings'; foul possessions leak into OTHER."
  },
  {
   "id": "FAM:SF-CHT-087",
   "what_failed": "Testing robustness of portability median Delta to mover pairing rules",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw), LIM:confounding, LIM:small_sample. Organizer-connector gap CI includes 0 after correcting a menu-similarity confound."
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Measuring persistent impact score of play-type actions",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw), LIM:confounding. Flat non-decaying lifts collapse under within-team baseline; team-quality confound."
  },
  {
   "id": "FAM:SF-APPS-073",
   "what_failed": "Measuring persistent impact score lag curves for play types",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw). Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1."
  }
 ],
 "evidence_establishes": [
  "There is historical evidence supporting the hypothesis that cut share predicts connector portability (FAM:SF-CHT-057).",
  "The reliability of play-type labels, particularly for 'DRIVE' and 'OTHER', has been audited and found to have systematic issues, including low confidence and incorrect foul-draw rates (FAM:SF-APPM-014).",
  "Measuring player impact and portability is susceptible to confounding by team quality and requires careful within-team analysis (FAM:SF-CHT-029, FAM:SF-APPS-073, FAM:SF-CHT-087).",
  "DRIVE PPP differs significantly between the regular season and playoffs, suggesting context dependency for drive-heavy roles (FAM:SF-APPS-011).",
  "Small sample sizes are a recurring limitation in studies of player movement and role portability (FAM:SF-CHT-057, FAM:SF-CHT-087, FAM:SF-APPM-014)."
 ],
 "evidence_does_not_establish": [
  "Whether the 'shaper' role in the current research question is equivalent to the 'connector' role studied previously.",
  "A robust, validated method for classifying players as 'cut-heavy' or 'drive-heavy' shapers that accounts for the identified play-type label issues.",
  "The specific mechanisms or reasons why cut-heavy roles might be more portable.",
  "The precise definition of 'travel better' in terms of specific performance metrics or impact measures."
 ],
 "own_inferences": [
  "The historical finding on 'connector portability' (FAM:SF-CHT-057) is very close to the current research question, suggesting that a similar effect might exist for 'shapers'.",
  "The known issues with play-type label accuracy (FAM:SF-APPM-014) pose a significant risk to any study relying on these labels for player classification or impact measurement.",
  "The difference in DRIVE PPP between regular season and playoffs (FAM:SF-APPS-011) implies that 'travel better' needs to consider consistency across different game contexts, not just different teams."
 ],
 "uncertainties": [
  "The precise definition of 'shaper' and how it relates to 'connector' or other player roles.",
  "How to reliably classify players as 'cut-heavy' or 'drive-heavy' given the known issues with play-type labels.",
  "The specific metric to quantify 'travel better' (e.g., change in PPP, plus/minus, role reproduction fidelity).",
  "The number of 'shaper' movers available in the dataset for adequate statistical power."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence, particularly FAM:SF-CHT-057, indicates that a similar hypothesis regarding cut/drive share and portability has already been supported. This shifts the current research from an exploratory question to one needing to replicate or refine prior findings, especially by addressing the identified methodological risks. Critically, FAM:SF-APPM-014 highlights severe issues with play-type labels, which are foundational to classifying players as 'cut-heavy' or 'drive-heavy'. This significantly increases the perceived risk of an artifactual result and necessitates a pre-analysis audit or robust re-labeling effort, changing the decision from a straightforward 'proceed' to 'proceed_with_changes'."
 },
 "testability": {
  "p_testable": 0.5,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "Systematic issues with play-type labels (DRIVE, OTHER, low confidence) undermine player classification as 'cut-heavy' or 'drive-heavy' and the reliability of impact measurements. A robust re-labeling or auditing process is required."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "The previous supporting study (FAM:SF-CHT-057) was limited by a small sample size (n=92 movers). The current dataset (n=24 units) might not yield enough 'shaper' movers for adequate power, especially after filtering for transfers and robust classification."
   },
   {
    "code": "CONFOUNDING",
    "text": "Player impact and portability studies are highly susceptible to confounding by team quality, surrounding talent, and changes in role definition, requiring careful control through within-team baselines or matched-pair analysis."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-CHT-057"
  ],
  "summary": "A previous study (FAM:SF-CHT-057) found support for the hypothesis that pre-move cut share (vs drive share) predicts the portability of a 'connector's organizational function' after a move. This is very similar to the current question regarding 'shapers' roles traveling better. However, that study was limited by sample size, and significant methodological risks related to play-type label accuracy have been identified since then."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The classification of players as 'cut-heavy' or 'drive-heavy' relies on play-type labels, which have known systematic issues (FAM:SF-APPM-014). This could lead to misclassification and artifactual results."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "The available data provides n=24 units. The number of 'shaper' players who transfer teams within this dataset might be too small to achieve useful statistical power, especially given that a prior supporting study (FAM:SF-CHT-057) was already limited by n=92 movers."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player portability is confounded by changes in team context, coaching schemes, surrounding teammates' skill sets, and player development/regression. Without careful controls (e.g., within-player delta, matched controls), observed 'portability' might be due to these factors rather than role characteristics (FAM:SF-CHT-029, FAM:SF-APPS-073, FAM:SF-CHT-087)."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "The definition of 'travel better' as an outcome needs to be robust and not inadvertently reflect factors that correlate with the player's initial role classification."
  },
  {
   "code": "MECHANICAL_FLOOR",
   "text": "If 'cut-heavy' or 'drive-heavy' is defined by a proportion, players with very low total play volume might have unstable classifications. Also, if there's a floor to how 'bad' a role can 'travel', it could bias results."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Player roles and team schemes can evolve over seasons. Comparing player roles across multiple seasons without accounting for potential drift in play definitions or league-wide trends could introduce bias."
  }
 ],
 "predicted_outcome": {
  "supported": 0.3,
  "rejected": 0.2,
  "untestable": 0.3,
  "artifact": 0.2,
  "uncertain": 0.0
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The difference in the change in on-court offensive impact (e.g., Delta PPP over expected, or adjusted on/off impact) after a player transfers teams, comparing players classified as 'cut-heavy shapers' versus 'drive-heavy shapers'. The 'change' is measured as (Post-Move Impact) - (Pre-Move Impact).",
  "unit": "Player-transfer event (a player moving from Team A to Team B between seasons). Each player-transfer event constitutes one unit of observation.",
  "sample": "NBA players who transferred teams (excluding retirements, long-term injuries preventing play) between the 2022-23 and 2025-26 seasons. Players must have played a minimum threshold of possessions (e.g., 500 possessions) in both the season prior to transfer (pre-move) and the season immediately after transfer (post-move) on their new team. Players will be classified as 'shapers' based on a predefined threshold of involvement in initiating possessions. Among shapers, they will be classified as 'cut-heavy' or 'drive-heavy' based on the ratio of their initiated 'CUT' possessions to 'DRIVE' possessions, using a validated and audited play-type dataset. Smallest relevant sample size for power will be assessed after player classification and filtering.",
  "power": "Based on FAM:SF-CHT-057 (n=92 movers), a similar sample size would be desirable. With n=24 total units of data, the actual number of eligible player-transfer events might be significantly smaller. A power analysis will be conducted once the eligible sample size of 'shaper' movers is determined after data preparation and classification. If the sample is too small (e.g., <50 movers), the study will be deemed underpowered and not proceed.",
  "controls": "1. **Play-type Label Audit/Validation:** Before player classification, conduct a rigorous audit and, if necessary, re-labeling or adjustment of the 'CUT' and 'DRIVE' play-type data, specifically addressing the issues raised in FAM:SF-APPM-014 (e.g., low confidence, foul-draw rates). This will be a prerequisite. 2. **Player Role Definition:** Define 'shaper' as players initiating >X% of team possessions. 'Cut-heavy' and 'drive-heavy' will be defined by the ratio of CUT to DRIVE possessions, or share of total initiated possessions. 3. **Within-Player Delta:** Use a within-player change score (post-move impact minus pre-move impact) to control for inherent player ability. 4. **Confounding Variables:** Control for relevant player characteristics (age, experience, position) and team characteristics (team quality, coaching change, presence of other stars) in a regression framework or via matched-pair analysis if feasible. 5. **Contextual Controls:** Account for regular season vs. playoff performance differences (FAM:SF-APPS-011) by either restricting the analysis to regular season only or including context as a control variable.",
  "falsification": "A falsification test will involve assessing if the observed effect holds when player classifications are randomly shuffled within the 'shaper' group, or if the effect disappears when controlling for a known confounding factor not directly related to role type (e.g., a simple change in team win percentage unrelated to player impact).",
  "multiplicity": "The primary hypothesis is directional. No multiple testing correction is planned for this single primary hypothesis. If exploratory analyses are conducted (e.g., different definitions of 'shaper' or 'portability'), these will be clearly labeled as such and results interpreted with caution.",
  "decision_rule": "The hypothesis will be considered supported if the confidence interval for the mean difference in portability (cut-heavy vs. drive-heavy shapers) excludes zero in the hypothesized direction (cut-heavy > drive-heavy) at p < 0.05, and the effect size is considered practically meaningful (e.g., Cohen's d > 0.2). If the CI includes zero and the study is adequately powered, the hypothesis will be rejected. If power is insufficient, it will be inconclusive.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs. NBA 2025-26 regular season (complete) and playoffs (complete). Per-game files from the NBA stats API, derived play-type possession records."
 }
}

